"""Two-state Contents, shared inline actions and guarded selected-title rename."""
import json
import time


def run_inline_checks(*,cdp,e,check,wait_for,add,shot):
    q=json.dumps
    root=add('Inline fixture');body=add('Reading and working',root);other=add('Other inspection',root)
    wait_for('physics.settled');e('physics.pause();hierarchySidebar.setCollapsed(true)')
    e(f"""(async()=>{{await saveEntryContent({q(body)},c=>({{...c,notes:{{format:'plain',text:'Long reading note.\\n'.repeat(180)}},links:Array.from({{length:24}},(_,i)=>({{id:'inline-link-'+i,url:'https://example.com/'+i,title:'Saved Link '+i}}))}}));await saveEntryLocation({q(body)},{{text:'Library'}});
    selectEntry(entries.get({q(body)}),nodes.get({q(body)}));await contentInspector.upload(Array.from({{length:12}},(_,i)=>new File(['Original '+i],'file-'+i+'.txt',{{type:'text/plain'}})));}})()""")
    e('window.inlineViewport=window.visualViewport')

    def frame():e('new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))')
    def settle():
        wait_for("!panel.getAnimations().some(a=>a.playState==='running')")
        e("""new Promise(resolve=>{let old='',stable=0;function sample(){const next=[mobileContents.root,...mobileContents.root.querySelectorAll('*')].map(n=>n.scrollTop+','+n.scrollLeft).join(';');stable=next===old?stable+1:0;old=next;if(stable>=8)resolve();else requestAnimationFrame(sample)}requestAnimationFrame(sample)})""")
    def viewport(width,height):
        cdp.call('Emulation.setDeviceMetricsOverride',width=width,height=height,deviceScaleFactor=1,mobile=width<1000)
        cdp.call('Emulation.setTouchEmulationEnabled',enabled=width<1000,maxTouchPoints=5)
        wait_for('camera.frame===null');settle()
    def inspect(id=body,page='notes'):
        e(f'selectEntry(entries.get({q(id)}),nodes.get({q(id)}),{{openInspector:true,reframe:false}});mobileContents.setPage({q(page)});physics.pause()');settle()
    def point(selector):
        return e(f"(()=>{{const b=document.querySelector({q(selector)}),r=b.getBoundingClientRect(),v=cosmosVisibleViewport(),clip=b.closest('#panel-rich-content')?mobileContents.root.getBoundingClientRect():{{top:v.top,bottom:v.top+v.height}},top=Math.max(r.top,clip.top),bottom=Math.min(r.bottom,clip.bottom);return {{x:r.x+Math.min(30,r.width/2),y:top+Math.min(24,(bottom-top)/2)}}}})()")
    def tap(selector):
        settle();p=point(selector)
        check(e(f'document.querySelector({q(selector)}).contains(document.elementFromPoint({p["x"]},{p["y"]}))'),'native target exposed: '+selector)
        cdp.call('Input.dispatchTouchEvent',type='touchStart',touchPoints=[p]);cdp.call('Input.dispatchTouchEvent',type='touchEnd',touchPoints=[]);settle()
    def swipe(selector,dy):
        settle();p=point(selector)
        cdp.call('Input.dispatchTouchEvent',type='touchStart',touchPoints=[p])
        for fraction in [.2,.4,.7,1]:
            cdp.call('Input.dispatchTouchEvent',type='touchMove',touchPoints=[dict(x=p['x'],y=p['y']+dy*fraction)]);time.sleep(.02)
        cdp.call('Input.dispatchTouchEvent',type='touchEnd',touchPoints=[]);settle()
    def keyboard(width,height):
        e(f'Object.defineProperty(window,"visualViewport",{{configurable:true,value:{{offsetLeft:0,offsetTop:12,width:{width},height:{height}}}}});mobileViewportChanged()');settle()
    def restore():
        e('Object.defineProperty(window,"visualViewport",{configurable:true,value:inlineViewport});mobileViewportChanged()');settle()
    def input_value(selector,value):
        e(f'(()=>{{const i=document.querySelector({q(selector)});i.value={q(value)};i.dispatchEvent(new Event("input",{{bubbles:true}}))}})()');frame()
    def actions(form,field,label):
        check(e(f"(()=>{{const f=document.querySelector({q(form)}),a=f.querySelector('.inline-editor-actions'),s=getComputedStyle(a);return getComputedStyle(f).borderTopWidth==='1px'&&getComputedStyle(f.querySelector('input,textarea')).outlineStyle==='none'&&s.borderLeftWidth==='0px'&&s.borderTopWidth==='0px'&&s.backgroundColor==='rgba(0, 0, 0, 0)'&&s.boxShadow==='none'&&[...a.children].every(b=>getComputedStyle(b).borderTopWidth==='0px'&&getComputedStyle(b).boxShadow==='none')}})()"),label+': one outer editor surface without an action compartment')
        metrics=e(f"""(()=>{{const f=document.querySelector({q(form)}),i=document.querySelector({q(field)}),r=i.getBoundingClientRect(),fields=f.querySelector('.inline-editor-fields').getBoundingClientRect(),a=f.querySelector('.inline-editor-actions').getBoundingClientRect(),v=cosmosVisibleViewport();return {{visible:Math.min(r.bottom,fields.bottom,v.top+v.height)-Math.max(r.top,fields.top,v.top),reserved:r.right<=a.left+1,inline:a.top>=f.getBoundingClientRect().top&&a.bottom<=f.getBoundingClientRect().bottom+1,buttons:[...f.querySelectorAll('button')].map(b=>{{const r=b.getBoundingClientRect(),s=b.querySelector('svg').getBoundingClientRect();return {{name:b.ariaLabel,w:r.width,h:r.height,visible:r.top>=v.top&&r.bottom<=v.top+v.height,hit:b.contains(document.elementFromPoint(r.x+r.width/2,r.y+r.height/2)),center:Math.abs(r.x+r.width/2-s.x-s.width/2)<1&&Math.abs(r.y+r.height/2-s.y-s.height/2)<1,labelHidden:getComputedStyle(b.querySelector('span')).display==='none'}}}})}}}})()""")
        check(metrics['visible']>=32 and metrics['reserved'] and metrics['inline'] and [b['name'] for b in metrics['buttons']]==['Save','Cancel'] and all(b['w']==44 and b['h']==44 and b['visible'] and b['hit'] and b['center'] and b['labelHidden'] for b in metrics['buttons']),label+': inline icons, visible field, reserved text space and 44px targets: '+q(metrics))

    for width,height in [(360,800),(390,844),(430,932),(844,390)]:
        viewport(width,height);inspect(other,'files')
        check(e("!document.getElementById('contents-expand-button')&&!('expanded' in mobileContents)&&!('setExpanded' in mobileContents)&&!panel.hasAttribute('data-contents-expanded')"),f'{width}: no Expanded state, control or method remains')
        empty=e('panel.getBoundingClientRect().height')
        check(empty<=200,f'{width}: empty Contents stays small')
        e(f"saveEntryContent({q(other)},c=>({{...c,notes:{{format:'plain',text:''}}}}))")
        inspect(body);inspect(other,'notes')
        check(e('!mobileContents.noteAdd.hidden&&contentInspector.notesView.hidden'),f'{width}: empty Notes exposes Add note')
        tap('#content-browse-add-note');input_value('#content-notes','First saved note.');tap('#content-notes-form button[type="submit"]')
        wait_for('contentInspector.notesForm.hidden')
        check(e('mobileContents.noteAdd.hidden&&!contentInspector.notesView.hidden&&contentInspector.notesView.textContent==="First saved note."&&contentInspector.status.hidden'),f'{width}: first Note replaces Add note without success feedback')
        tap('#content-notes-view')
        check(e('!contentInspector.notesForm.hidden&&contentInspector.notes.value==="First saved note."'),f'{width}: clean saved text tap edits the existing Note')
        input_value('#content-notes','Updated note.');tap('#content-notes-form button[type="submit"]');wait_for('contentInspector.notesForm.hidden')
        tap('#content-notes-view');input_value('#content-notes','Discarded note.');tap('#content-cancel-notes')
        check(e('contentInspector.content().notes.text==="Updated note."&&contentInspector.notesView.textContent==="Updated note."&&mobileContents.noteAdd.hidden'),f'{width}: cancel restores saved Note without an Add row')
        e(f"saveEntryContent({q(other)},c=>({{...c,notes:{{format:'plain',text:'Short note.'}}}}))")
        inspect(body);inspect(other)
        short=e('panel.getBoundingClientRect().height')
        check(short<=280 and e('!contentInspector.notesView.hidden'),f'{width}: short saved Note fits adaptive Contents')
        e(f"saveEntryContent({q(other)},c=>({{...c,notes:{{format:'plain',text:'Medium note.\\n'.repeat(3)}}}}))")
        inspect(body);inspect(other)
        check(e('panel.getBoundingClientRect().height')>short or width>700,f'{width}: medium Note grows toward the practical cap')
        inspect()
        check(e('panel.getBoundingClientRect().height<=Math.min(Math.max(280,cosmosVisibleViewport().height*.38),cosmosVisibleViewport().height*.60)+1&&mobileContents.root.scrollHeight>mobileContents.root.clientHeight'),f'{width}: long Note caps at normal medium height and scrolls')
        for page,selector in [('notes','#content-notes-view'),('links','#content-links'),('files','#content-attachments')]:
            e(f'mobileContents.setPage({q(page)})');settle();before=e('panel.getBoundingClientRect().height')
            swipe(selector,-90)
            check(e('mobileContents.root.scrollTop>0&&!panel.hidden&&contentInspector.notesForm.hidden&&selectedTitleEditors.every(editor=>!editor.edit)') and abs(e('panel.getBoundingClientRect().height')-before)<1,f'{width}/{page}: list scroll cannot grow/collapse the sheet or rename')
        e("mobileContents.setPage('notes');mobileContents.root.scrollTop=0");settle()
        swipe('#close-inspector-button',-90)
        check(e('mobileContents.state==="browse"&&!panel.hidden'),f'{width}: upward Contents handle has no extra level')
        shot('simple-contents-'+str(width))

        # Shared mobile editor actions preserve the existing save/cancel handlers.
        for page,activate,form,field,cancel,value in [
            ('notes','contentInspector.editNotes()','#content-notes-form','#content-notes','#content-cancel-notes','Draft text.\n'*120),
            ('links','contentInspector.addBookmark()','#content-bookmarks-empty','#content-quick-bookmark-url','#content-cancel-quick-bookmark','https://example.com/new-'+str(width)),
            ('location','contentInspector.editLocation()','#content-location-form','#content-location-input','#content-cancel-location','New place '+str(width))]:
            inspect(page=page);e(activate);input_value(field,value);keyboard(width,190 if width>700 else 340)
            actions(form,field,f'{width}/{page}/keyboard')
            shot('unified-editor-'+page+'-'+str(width))
            check(e('!mobileContents.dock.hidden&&getComputedStyle(mobileContents.dock).display==="flex"'),f'{width}/{page}: tabs remain available beside the keyboard-aware editor')
            swipe(field,80)
            check(e('!panel.hidden&&mobileContents.state==="browse"'),f'{width}/{page}: editing gesture belongs to its editor')
            if page=='notes':
                check(e('contentInspector.notes.scrollHeight>contentInspector.notes.clientHeight'),f'{width}: long textarea scrolls internally')
                e("mobileContents.setPage('files');mobileContents.setPage('notes')");settle()
                check(e('contentInspector.notes.value')==value,f'{width}: draft survives tab switching')
            if page=='links':
                check(e('document.getElementById("content-links").scrollHeight>document.getElementById("content-links").clientHeight&&getComputedStyle(document.getElementById("content-links")).overflowY==="auto"'),f'{width}: saved Links keep an independent scrolling area')
                input_value(field,'javascript:alert(1)');tap(form+' button[type="submit"]')
                wait_for('contentInspector.quickUrl.getAttribute("aria-invalid")==="true"');actions(form,field,f'{width}/invalid Link')
                check(e('contentInspector.quickBookmark.contains(contentInspector.status)&&contentInspector.status.dataset.error==="true"'),f'{width}: invalid URL feedback stays in its field scroller')
                input_value(field,value)
            tap(form+' button[type="submit"]');wait_for(f'document.querySelector({q(form)}).hidden')
            check(e('contentInspector.content().notes.text')==value if page=='notes' else e('contentInspector.content().links.some(l=>l.url==='+q(value)+')') if page=='links' else e('entries.get('+q(body)+').location.text')==value,f'{width}/{page}: checkmark persists exact content')
            check(e('contentInspector.status.hidden'),f'{width}/{page}: successful save clears stale feedback without a success message')
            shot('unified-editor-saved-'+page+'-'+str(width))
            if page=='links':check(e('!document.getElementById("content-add-bookmark").closest("p").hidden'),f'{width}: Add link remains available with multiple saved Links')
            saved=e('JSON.stringify({content:contentInspector.content(),location:entries.get('+q(body)+').location})')
            restore();e(activate);input_value(field,'Cancelled draft');keyboard(width,190 if width>700 else 340)
            actions(form,field,f'{width}/{page}/Cancel');tap(cancel)
            check(e(f'document.querySelector({q(form)}).hidden') and e('JSON.stringify({content:contentInspector.content(),location:entries.get('+q(body)+').location})')==saved,f'{width}/{page}: cross cancels without changing saved content')
            restore()
        # Restore the long saved Note for the next size case.
        e(f"saveEntryContent({q(body)},c=>({{...c,notes:{{format:'plain',text:'Long reading note.\\n'.repeat(180)}}}}))")
        inspect();e('closeInspector()');settle()
        preview='#mobile-body-actions .selected-title';header='#entry-panel .selected-title'
        check(e('document.querySelectorAll(".title-pencil").length===0'),f'{width}: neither selected title contains a pencil')
        swipe(preview,12)
        check(e('selectedTitleEditors.every(editor=>!editor.edit)&&panel.hidden'),f'{width}: meaningful title movement does not rename')
        p=point(preview)
        cdp.call('Input.dispatchTouchEvent',type='touchStart',touchPoints=[p])
        cdp.call('Input.dispatchTouchEvent',type='touchMove',touchPoints=[dict(x=p['x']+20,y=p['y'])])
        cdp.call('Input.dispatchTouchEvent',type='touchMove',touchPoints=[p])
        cdp.call('Input.dispatchTouchEvent',type='touchEnd',touchPoints=[]);settle()
        check(e('selectedTitleEditors.every(editor=>!editor.edit)&&panel.hidden'),f'{width}: moving away and back still cancels the title tap')
        p=point(preview)
        cdp.call('Input.dispatchTouchEvent',type='touchStart',touchPoints=[dict(p,id=1)])
        cdp.call('Input.dispatchTouchEvent',type='touchStart',touchPoints=[dict(p,id=1),dict(x=p['x']+18,y=p['y'],id=2)])
        cdp.call('Input.dispatchTouchEvent',type='touchEnd',touchPoints=[]);settle()
        check(e('selectedTitleEditors.every(editor=>!editor.edit)'),f'{width}: multi-touch cannot enter rename')
        tap(preview)
        check(e('!!selectedTitleEditors[0].edit&&!selectedTitleEditors[0].form.hidden&&document.activeElement===selectedTitleEditors[0].input&&!dialog.open'),f'{width}: clean Preview title tap enters inline rename')
        input_value(preview+' input','Renamed '+str(width));keyboard(width,190 if width>700 else 340)
        actions(preview+' form',preview+' input',f'{width}/Preview rename')
        shot('inline-preview-rename-'+str(width));tap(preview+' button[type="submit"]')
        wait_for(f'entries.get({q(body)}).name==={q("Renamed "+str(width))}&&!selectedTitleEditors[0].edit');restore()
        check(e('document.getElementById("mobile-body-name").textContent')=='Renamed '+str(width),f'{width}: rename publishes the original CB name')
        tap(preview);input_value(preview+' input','Discarded name');tap(preview+' button[type="button"]')
        check(e('entries.get('+q(body)+').name')=='Renamed '+str(width),f'{width}: title opens the same editor and Cancel retains original name')
        tap(preview);input_value(preview+' input','   ');tap(preview+' button[type="submit"]')
        wait_for('selectedTitleEditors[0].input.getAttribute("aria-invalid")==="true"')
        check(e('!!selectedTitleEditors[0].edit&&selectedTitleEditors[0].input.validationMessage==="Enter a name."'),f'{width}: rename uses existing validation and keeps invalid draft')
        tap(preview+' button[type="button"]')
        swipe(preview,-90);wait_for('!panel.hidden')
        check(e('mobileContents.state==="browse"&&selectedTitleEditors.every(editor=>!editor.edit)'),f'{width}: title-origin swipe opens Contents without rename')
        tap(header);input_value(header+' input','Header '+str(width));keyboard(width,190 if width>700 else 340)
        actions(header+' form',header+' input',f'{width}/Contents rename above keyboard')
        check(e('mobileContents.dock.getBoundingClientRect().bottom<=cosmosVisibleViewport().top+cosmosVisibleViewport().height+1'),f'{width}: keyboard-open title rename keeps the tabs inside the visible viewport: '+q(e('({dock:mobileContents.dock.getBoundingClientRect().toJSON(),panel:panel.getBoundingClientRect().toJSON(),visible:cosmosVisibleViewport()})')))
        check(e('(()=>{const f=selectedTitleEditors[1].form.getBoundingClientRect();return ["entry-add-button","entry-more-button"].every(id=>{const b=document.getElementById(id),r=b.getBoundingClientRect();return r.width===44&&r.height===44&&r.left>=f.right&&b.contains(document.elementFromPoint(r.x+r.width/2,r.y+r.height/2))})})()'),f'{width}: rename keeps independent Add/More targets clear of the input')
        tap('#entry-add-button');check(e('!addMenu.hidden&&addMenuTargetId==='+q(body)+'&&!!selectedTitleEditors[1].edit'),f'{width}: Add retains its CB while title editing');e('closeContentMenus()')
        tap('#entry-more-button');check(e('!contextMenu.hidden&&contextEntryId==='+q(body)+'&&!!selectedTitleEditors[1].edit'),f'{width}: More retains its CB while title editing');e('closeContextMenu()')
        shot('inline-contents-rename-'+str(width));tap(header+' button[type="submit"]')
        wait_for(f'entries.get({q(body)}).name==={q("Header "+str(width))}&&!selectedTitleEditors[1].edit')
        restore()
        swipe(header,90);wait_for('panel.hidden')
        check(e('selectedTitleEditors.every(editor=>!editor.edit)&&mobileContents.state==="compact"'),f'{width}: title-origin down swipe returns directly to Compact without rename')
        inspect();e('moreButton.click();contextMenu.querySelector("button[data-action=edit]").click()')
        check(e('dialog.open&&document.getElementById("add-entry-title").textContent==="Rename item"'),f'{width}: More/Rename keeps its existing alternate path')
        e('document.getElementById("cancel-add-entry").click()');settle()
        e('selectedTitleEditors[1].host.focus()')
        cdp.call('Input.dispatchKeyEvent',type='keyDown',key='Enter',code='Enter',windowsVirtualKeyCode=13)
        cdp.call('Input.dispatchKeyEvent',type='keyUp',key='Enter',code='Enter',windowsVirtualKeyCode=13);settle()
        check(e('!!selectedTitleEditors[1].edit&&document.activeElement===selectedTitleEditors[1].input'),f'{width}: title rename is keyboard accessible')
        input_value(header+' input','Escape draft')
        cdp.call('Input.dispatchKeyEvent',type='keyDown',key='Escape',code='Escape',windowsVirtualKeyCode=27)
        cdp.call('Input.dispatchKeyEvent',type='keyUp',key='Escape',code='Escape',windowsVirtualKeyCode=27);settle()
        check(e('!selectedTitleEditors[1].edit&&!panel.hidden&&entries.get('+q(body)+').name==='+q('Header '+str(width))),f'{width}: Escape cancels rename without collapsing Contents')
        e('selectedTitleEditors[1].host.focus()')
        cdp.call('Input.dispatchKeyEvent',type='keyDown',key=' ',code='Space',windowsVirtualKeyCode=32)
        cdp.call('Input.dispatchKeyEvent',type='keyUp',key=' ',code='Space',windowsVirtualKeyCode=32)
        check(e('!!selectedTitleEditors[1].edit'),f'{width}: Space also activates the title control')
        e('selectedTitleEditors[1].form.querySelector("button[type=button]").focus()')
        cdp.call('Input.dispatchKeyEvent',type='keyDown',key='Enter',code='Enter',windowsVirtualKeyCode=13,text='\r',unmodifiedText='\r')
        cdp.call('Input.dispatchKeyEvent',type='keyUp',key='Enter',code='Enter',windowsVirtualKeyCode=13);settle()
        check(e('!selectedTitleEditors[1].edit&&!panel.hidden'),f'{width}: keyboard Cancel closes once without reopening rename')
        tap(header);input_value(header+' input','Unrelated draft');inspect(other)
        check(e('selectedTitleEditors.every(editor=>!editor.edit)&&contentInspector.entryId==='+q(other)),f'{width}: changing CB cancels the previous title draft safely')

    viewport(1440,1000);inspect()
    check(e('selectedTitleEditors.every(editor=>!editor.edit&&!editor.host.hasAttribute("role"))&&document.querySelectorAll("[data-sheet-title]").length===0'), 'desktop titles keep their existing interaction')
    check(e('(()=>{const event=new MouseEvent("click",{bubbles:true,cancelable:true});return panelName.dispatchEvent(event)&&!event.defaultPrevented&&!selectedTitleEditors[1].edit})()'), 'desktop title clicks are not intercepted by the mobile editor')
    e('contentInspector.editNotes()');frame()
    check(e('[...document.querySelectorAll("#content-notes-form .inline-editor-actions button")].every(b=>getComputedStyle(b.querySelector("span")).display!=="none"&&getComputedStyle(b.querySelector("svg")).display==="none")'), 'desktop retains Save/Cancel text buttons')
    check(not cdp.errors,'no mobile inline editor browser exceptions: '+q(cdp.errors))
